    // ==========================================
    // 0. Distribution Comparison at t=1000 (Section 1)
    // ==========================================
    const distCanvas = document.getElementById('ouDistCanvas');
    if (distCanvas) {
        const ctxDist = distCanvas.getContext('2d');
        const edges = DATA.bin_edges;
        const hEm = DATA.hist_em;
        const hExact = DATA.hist_exact;
        const pdfX = DATA.pdf_x;
        const pdfY = DATA.pdf_y;

        const minX = edges[0], maxX = edges[edges.length - 1];
        const maxY = Math.max(...hExact, ...hEm, ...pdfY) * 1.08;

        function drawDist() {
            const rect = distCanvas.parentElement.getBoundingClientRect();
            distCanvas.width = rect.width * window.devicePixelRatio;
            distCanvas.height = rect.height * window.devicePixelRatio;
            ctxDist.scale(window.devicePixelRatio, window.devicePixelRatio);

            const w = rect.width, h = rect.height, pad = 15;
            const drawW = w - 2 * pad, drawH = h - 2 * pad;

            ctxDist.clearRect(0, 0, w, h);

            const mapX = (val) => pad + ((val - minX) / (maxX - minX)) * drawW;
            const mapY = (val) => pad + drawH - (val / maxY) * drawH;
            const baseLine = pad + drawH;

            // 1. Euler-Maruyama Histogram Bars (Gruvbox Blue, translucent)
            ctxDist.fillStyle = 'rgba(131, 165, 152, 0.35)';
            ctxDist.strokeStyle = 'rgba(131, 165, 152, 0.85)';
            ctxDist.lineWidth = 1.0;
            for (let i = 0; i < hEm.length; i++) {
                const x0 = mapX(edges[i]);
                const x1 = mapX(edges[i + 1]);
                const y = mapY(hEm[i]);
                ctxDist.fillRect(x0, y, x1 - x0, baseLine - y);
                ctxDist.strokeRect(x0, y, x1 - x0, baseLine - y);
            }

            // 2. Exact Step Histogram Bars (Gruvbox Orange, translucent)
            ctxDist.fillStyle = 'rgba(214, 93, 14, 0.45)';
            ctxDist.strokeStyle = 'rgba(214, 93, 14, 0.9)';
            ctxDist.lineWidth = 1.0;
            for (let i = 0; i < hExact.length; i++) {
                const x0 = mapX(edges[i]);
                const x1 = mapX(edges[i + 1]);
                const y = mapY(hExact[i]);
                ctxDist.fillRect(x0, y, x1 - x0, baseLine - y);
                ctxDist.strokeRect(x0, y, x1 - x0, baseLine - y);
            }

            // 3. Theoretical Gaussian PDF (Gruvbox Cream Dashed)
            ctxDist.save();
            ctxDist.beginPath();
            ctxDist.setLineDash([6, 4]);
            ctxDist.strokeStyle = '#ebdbb2';
            ctxDist.lineWidth = 2.0;
            for (let i = 0; i < pdfX.length; i++) {
                const x = mapX(pdfX[i]);
                const y = mapY(pdfY[i]);
                if (i === 0) ctxDist.moveTo(x, y);
                else ctxDist.lineTo(x, y);
            }
            ctxDist.stroke();
            ctxDist.restore();

            // Bottom baseline
            ctxDist.beginPath();
            ctxDist.moveTo(pad, baseLine);
            ctxDist.lineTo(w - pad, baseLine);
            ctxDist.strokeStyle = '#504945';
            ctxDist.lineWidth = 1.2;
            ctxDist.stroke();
        }

        drawDist();
        new ResizeObserver(drawDist).observe(distCanvas.parentElement);
    }

    // ==========================================
    // 1. Simulated OU Path (Section 1 / 2)
    // ==========================================
    const simCanvas = document.getElementById('ouSimCanvas');
    if (simCanvas) {
        const ctxSim = simCanvas.getContext('2d');
        const path = DATA.X;
        const steps = path.length - 1;

        const bound = Math.max(Math.abs(Math.min(...path, -1.5)), Math.abs(Math.max(...path, 1.5)));
        const minVal = -bound, maxVal = bound, rangeVal = maxVal - minVal;

        function drawSim() {
            const rect = simCanvas.parentElement.getBoundingClientRect();
            simCanvas.width = rect.width * window.devicePixelRatio;
            simCanvas.height = rect.height * window.devicePixelRatio;
            ctxSim.scale(window.devicePixelRatio, window.devicePixelRatio);

            const w = rect.width, h = rect.height, pad = 15;
            const drawW = w - 2 * pad, drawH = h - 2 * pad;

            ctxSim.clearRect(0, 0, w, h);

            // Center zero line (mu = 0.0)
            const zeroY = pad + drawH - ((DATA.mu_true - minVal) / rangeVal) * drawH;
            ctxSim.beginPath();
            ctxSim.moveTo(pad, zeroY);
            ctxSim.lineTo(w - pad, zeroY);
            ctxSim.strokeStyle = '#504945';
            ctxSim.lineWidth = 1.2;
            ctxSim.stroke();

            // Simulated OU Path (Gruvbox Orange)
            ctxSim.beginPath();
            ctxSim.strokeStyle = '#d65d0e';
            ctxSim.lineWidth = 1.5;

            for (let i = 0; i <= steps; i++) {
                const x = pad + (i / steps) * drawW;
                const y = pad + drawH - ((path[i] - minVal) / rangeVal) * drawH;
                if (i === 0) ctxSim.moveTo(x, y);
                else ctxSim.lineTo(x, y);
            }
            ctxSim.stroke();
        }

        drawSim();
        new ResizeObserver(drawSim).observe(simCanvas.parentElement);
    }

    // ==========================================
